import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'

import "../../scss/main.scss"

import Header from "../../components/Header"
import Footer from "../../components/Footer"
import AccentDots from "../../components/AccentDots"
import Seo from "../../components/Seo"

interface ImageNode {
  name: string
  childImageSharp: {
    thumb: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    images: { nodes: ImageNode[] }
    logo: { nodes: ImageNode[] }
  }
}

const techStack = [
  'Ruby on Rails', 'Carrierwave', 'Devise', 'Ransack',
  'Act As Votable', 'Bootstrap', 'CSS3'
]

const categories = [
  'Experimental', 'Video Mapping', 'Drawn on Film', 'Figurative', '3D'
]

const environments = [
  'Installation', 'Video Art', 'Music Festival', 'Performance', 'Music Video', 'Dev Art'
]

const MusartPage: React.FC<PageProps> = ({ data }) => {
  const [spotlightIndex, setSpotlightIndex] = React.useState<number | null>(null)
  const [dragY, setDragY] = React.useState(0)
  const [isDragging, setIsDragging] = React.useState(false)
  const [zoomScale, setZoomScale] = React.useState(1)
  const [zoomOrigin, setZoomOrigin] = React.useState({ x: 50, y: 50 })
  const initialPinchDistance = React.useRef(0)
  const lastScale = React.useRef(1)
  const touchStartY = React.useRef(0)

  const logo = data.logo.nodes[0] ? getImage(data.logo.nodes[0].childImageSharp.thumb) : null
  const screenshot = data.images.nodes.find(n => n.name === 'musart-screen')
  const wireframes = data.images.nodes.find(n => n.name === 'Musart_wrieframes')
  const erDiagram = data.images.nodes.find(n => n.name === 'Musart_ER')

  const spotlightImages = [screenshot, wireframes, erDiagram].filter(Boolean) as ImageNode[]

  const openSpotlight = (node: ImageNode) => {
    const idx = spotlightImages.indexOf(node)
    if (idx >= 0) setSpotlightIndex(idx)
  }

  const dismissThreshold = 120

  const getPinchDistance = (touches: React.TouchList) => {
    const dx = touches[0].clientX - touches[1].clientX
    const dy = touches[0].clientY - touches[1].clientY
    return Math.sqrt(dx * dx + dy * dy)
  }

  const handleTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      initialPinchDistance.current = getPinchDistance(e.touches)
      lastScale.current = zoomScale
    } else if (e.touches.length === 1 && zoomScale <= 1) {
      touchStartY.current = e.touches[0].clientY
      setIsDragging(true)
    }
  }

  const handleTouchMove = (e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      const dist = getPinchDistance(e.touches)
      const scale = Math.max(1, Math.min(4, lastScale.current * (dist / initialPinchDistance.current)))
      const midX = ((e.touches[0].clientX + e.touches[1].clientX) / 2 / window.innerWidth) * 100
      const midY = ((e.touches[0].clientY + e.touches[1].clientY) / 2 / window.innerHeight) * 100
      setZoomScale(scale)
      setZoomOrigin({ x: midX, y: midY })
    } else if (e.touches.length === 1 && zoomScale <= 1) {
      const delta = e.touches[0].clientY - touchStartY.current
      if (delta > 0) {
        setDragY(delta)
      }
    }
  }

  const handleTouchEnd = () => {
    if (zoomScale <= 1) {
      setIsDragging(false)
      if (dragY > dismissThreshold) {
        setSpotlightIndex(null)
        setZoomScale(1)
      }
      setDragY(0)
    }
  }

  return (
    <div className="container">
      <Header />

      <div className="case-study__hero">
        <Link to="/developer" className="back-link">&larr; Back to Developer</Link>
        <h1>Musart</h1>
        {logo && (
          <div className="case-study__logo-wrap">
            <GatsbyImage image={logo} alt="Musart logo" className="case-study__logo case-study__logo--large" />
          </div>
        )}
        <AccentDots />
      </div>

      <div className="case-study__body">
        <section className="case-study__section">
          <h2>Vision</h2>
          <p>
            Musart is a platform built to create an online community of artists who
            work with visuals and sound. The site focuses on connecting creatives
            across disciplines including experimental, video mapping, drawn on film,
            figurative, and 3D work.
          </p>
          <p>
            Artists working across installation, video art, music festivals,
            performance, music video, and dev art can showcase their projects,
            discover others, and connect for collaboration.
          </p>
          <p>
            Built during the General Assembly Web Development Immersive course.
          </p>
        </section>

        {screenshot && (() => {
          const img = getImage(screenshot.childImageSharp.thumb)
          return img ? (
            <section className="case-study__section">
              <h2>Screenshot</h2>
              <div className="case-study__image-wrap" onClick={() => openSpotlight(screenshot)}>
                <GatsbyImage image={img} alt="Musart screenshot" className="case-study__image" />
              </div>
            </section>
          ) : null
        })()}

        <section className="case-study__section">
          <h2>User Story</h2>
          <p>
            Artists can sign up, create a profile, and upload projects &mdash; work
            they have done. They can write information about each project, embed
            videos, and upload stills. Once you are a member of the community you can
            view other artists' work and their profiles for networking and
            collaboration purposes.
          </p>
        </section>

        {wireframes && (() => {
          const img = getImage(wireframes.childImageSharp.thumb)
          return img ? (
            <section className="case-study__section">
              <h2>Wireframes</h2>
              <div className="case-study__image-wrap" onClick={() => openSpotlight(wireframes)}>
                <GatsbyImage image={img} alt="Musart wireframes" className="case-study__image" />
              </div>
            </section>
          ) : null
        })()}

        {erDiagram && (() => {
          const img = getImage(erDiagram.childImageSharp.thumb)
          return img ? (
            <section className="case-study__section">
              <h2>ER Diagram</h2>
              <div className="case-study__image-wrap" onClick={() => openSpotlight(erDiagram)}>
                <GatsbyImage image={img} alt="Musart ER diagram" className="case-study__image" />
              </div>
            </section>
          ) : null
        })()}

        <section className="case-study__section">
          <h2>Categories</h2>
          <div className="case-study__pills">
            {categories.map((cat) => (
              <span key={cat} className="case-study__pill">{cat}</span>
            ))}
          </div>
        </section>

        <section className="case-study__section">
          <h2>Environments</h2>
          <div className="case-study__pills">
            {environments.map((env) => (
              <span key={env} className="case-study__pill">{env}</span>
            ))}
          </div>
        </section>

        <section className="case-study__section">
          <h2>Tech Stack</h2>
          <div className="case-study__pills">
            {techStack.map((tech) => (
              <span key={tech} className="case-study__pill">{tech}</span>
            ))}
          </div>
        </section>
      </div>

      {spotlightIndex !== null && (() => {
        const node = spotlightImages[spotlightIndex]
        const image = getImage(node.childImageSharp.thumb)
        const opacity = Math.max(0.2, 1 - dragY / 400)

        return (
          <div
            className="case-study__spotlight"
            onClick={() => { setSpotlightIndex(null); setZoomScale(1) }}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
            style={{ background: `rgba(0, 0, 0, ${opacity * 0.9})` }}
          >
            <div className="case-study__spotlight-hint">Swipe down to close · Pinch to zoom</div>
            <div
              className="case-study__spotlight-content"
              onClick={(e) => {
                e.stopPropagation()
                if (zoomScale > 1) setZoomScale(1)
              }}
              style={{
                transform: `translateY(${dragY}px) scale(${zoomScale})`,
                transformOrigin: `${zoomOrigin.x}% ${zoomOrigin.y}%`,
                transition: isDragging ? 'none' : 'transform 0.3s ease',
              }}
            >
              {image && (
                <GatsbyImage
                  image={image}
                  alt="Musart"
                  className="case-study__spotlight-image"
                />
              )}
            </div>
          </div>
        )
      })()}

      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query MusartQuery {
    images: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "musart" }
        extension: { in: ["png", "jpg", "jpeg"] }
        name: { ne: "musart" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        name
        childImageSharp {
          thumb: gatsbyImageData(width: 800, placeholder: BLURRED)
        }
      }
    }
    logo: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "musart" }
        name: { eq: "musart" }
      }
    ) {
      nodes {
        name
        childImageSharp {
          thumb: gatsbyImageData(width: 200, placeholder: BLURRED)
        }
      }
    }
  }
`

export const Head = () => <Seo title="MusArt" description="Where music meets art." />

export default MusartPage
